    {
      "theory_id": "va_exam_inadequacy",
      "theory_name": "VA Examination Inadequacy / Failure to Develop Record",
      "legal_framework": {
        "primary_statute": "38 CFR § 3.310 (implicitly requires adequate factfinding on causation)",
        "supporting_principle": "VA must obtain an examination adequate to fairly assess the claim, including causation elements.",
